// Router: geography → capacity → specialism.
// Three seed CTA partners: Westminster CTA Partners (London/SE), Manchester Tax Advisers (NW/Midlands), Newcastle Indirect Tax (NE/Scotland).
const customer = ($('Fetch customer').item.json[0]) || $('Fetch customer').item.json;
const partners = items.map(i => i.json);
const body = $('Webhook · CTA referral request').item.json.body || {};
const region = (customer.address_region || '').toLowerCase();
const topic = (body.topic || '').toLowerCase();
const triggers = body.detected_triggers || [];

// 1. Geography match
let pool = partners.filter(p => {
  const cov = (p.coverage_regions || []).map(r => String(r).toLowerCase());
  return cov.includes(region);
});
// 2. Specialism filter — if a specialism trigger is named, intersect
if (triggers.length) {
  const specialised = pool.filter(p => {
    const sp = (p.specialisms || []).map(s => String(s).toLowerCase());
    return triggers.some(t => sp.includes(String(t).toLowerCase()));
  });
  if (specialised.length) pool = specialised;
}
// 3. If empty after geography, fall back to all partners with specialism match
if (!pool.length && triggers.length) {
  pool = partners.filter(p => {
    const sp = (p.specialisms || []).map(s => String(s).toLowerCase());
    return triggers.some(t => sp.includes(String(t).toLowerCase()));
  });
}
// 4. Final fallback: any active partner
if (!pool.length) pool = partners;
// 5. Capacity sort: lowest open_referral_count wins; tie-break on id
pool.sort((a,b) => (a.open_referral_count||0) - (b.open_referral_count||0) || String(a.id).localeCompare(String(b.id)));
const chosen = pool[0];

return [{ json: {
  customer,
  partner: chosen,
  query: { text: body.query_text || '', topic, triggers, source_channel: body.source_channel || 'dashboard' },
  context_payload: body.context_payload || null,
  referral_id: 'VAT-REF-' + Date.now()
} }];
